update transaction_flow set is_unapproved = true,version = version + 1,
update_time = #{updateTime}, update_user_id = #{updateUserId}, update_user_name = #{updateUserName}
where id = #{id} and is_deleted = false

mapper.select:
SELECT t.id,t.trade_time, t.bill_date, t.source_type, t.source_code, t.operation_mode, t.sku_id, t.sku_no, t.warehouse_location, t.warehouse_id, t.warehouse_name, t.org_id, t.dict_inventory_status as inventory_status, t.qty, t.cur_inventory_qty as after_qty, t.instock_batch_date FROM transaction_flow t WHERE ${params.sqlMap.default} and t.is_deleted = false AND t.warehouse_id = #{params.warehouseId} AND t.sku_id = #{params.skuId}
AND t.warehouse_location = #{params.warehouseLocation}
AND t.org_id = #{params.orgId}
order by t.bill_date desc,t.id desc

SELECT t.id,t.trade_time, t.bill_date, t.source_type, t.source_code, t.operation_mode, t.sku_id, t.sku_no, t.warehouse_location, t.warehouse_id, t.warehouse_name, t.org_id, t.dict_inventory_status as inventory_status, t.qty, t.cur_inventory_qty as after_qty, t.instock_batch_date FROM transaction_flow t left join product_detail pd on pd.id = t.sku_id left join product_info pi on pd.product_id = pi.id left join product_sale ps on ps.sku_id = pd.id WHERE ${params.sqlMap.default} and t.is_deleted = false and ps.is_deleted = false AND t.warehouse_id = #{params.warehouseId} AND t.sku_id = #{params.skuId}
AND t.org_id = #{params.orgId}
and t.warehouse_location = #{params.warehouseLocation}
order by t.bill_date desc,t.id desc

SELECT t.id,t.trade_time AS tradeTime, t.bill_date AS billDate, t.source_type AS sourceType, t.source_code AS sourceCode, t.source_id AS sourceId, t.source_detail_id AS sourceDetailId, t.operation_mode AS operationMode, t.sku_id AS skuId, t.sku_no AS skuNo, t.warehouse_location AS warehouseLocation, t.warehouse_id AS warehouseId, t.warehouse_name AS warehouseName, t.org_id AS orgId, t.dict_inventory_status as inventoryStatus, t.qty, t.cur_inventory_qty as afterQty, t.instock_batch_date AS instockBatchDate, t.create_time AS createTime, t.update_time AS updateTime FROM transaction_flow t left join product_detail pd on pd.id = t.sku_id left join product_info pi on pd.product_id = pi.id left join product_sale ps on ps.sku_id = pd.id WHERE ${params.sqlMap.default} and t.is_deleted = false and ps.is_deleted = false
and t.dict_biz_type in ('00','02','03','04','05','07','08','09','11','12','13','14','17','18','19','20','23','24','26','15','16','27','29','30','32','33','34','35','49','50')
and t.sku_no in
#{item}
and t.source_code ilike concat('%', #{params.sourceCode}::text ,'%')
and t.source_type in
#{item}
and pi.spu_no in
#{item}
and ps.sale_state in
#{item}
and t.warehouse_id in
#{item}
and t.org_id in
#{item}
and t.trade_time >= #{params.dateList[0]} and (#{params.dateList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > t.trade_time
and t.bill_date >= #{params.billDateList[0]} and (#{params.billDateList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > t.bill_date
and t.is_unapproved = false
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
t.create_time desc

