and t.dict_biz_type in ('00','02','03','04','05','07','08','09','11','12','13','14','17','18','19','20','23','24','26','15','16','27','29','30','32','33','34','35')
and t.id in
#{item}
and t.sku_no in
#{item}
and t.source_code ilike concat('%', #{params.sourceCode}::text ,'%')
and t.source_type in
#{item}
